\label{thm: minus}
    Let $x_0 \in \mathbb N_0$, and let $(x_i)_{i \geqslant 0}$ be its orbit under $Q_-$.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item If $x_0 = 0$ or $x_0 = 2^l$ with $l \geqslant 0$, the orbit reaches the fixed point $0$.
        \item If $x_0 = 2^l (2^m + 1)$ with $l \geqslant 0$ and $m \geqslant 1$, the orbit enters the cycle of length $m$ that contains $2^m + 1$.
        \item For every other $x_0$, the orbit satisfies $x_i \to \infty$ as $i \to \infty$.
    \end{enumerate}

\label{thm: plus}
    Let $x_0 \in \mathbb N_0$, and let $(x_i)_{i \geqslant 0}$ be its orbit under $Q_+$.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item If $x_0 = 0$, the orbit stays at the fixed point $0$.
        \item If $x_0 = 2^l (2^m - 1)$ with $l \geqslant 0$ and $m \geqslant 1$, the orbit enters the cycle of length $m$ that contains $2^m - 1$, which for $m = 1$ is the fixed point $1$.
        \item If $x_0 = 5 \cdot 2^l$ with $l \geqslant 0$, the orbit enters the cycle $15 \to 120 \to 60 \to 30 \to 15$ through $15 = 2^4 - 1$.
        \item For every other $x_0$, the orbit satisfies $x_i \to \infty$ as $i \to \infty$.
    \end{enumerate}

\label{thm: S}
    Let $x_0 \in \mathbb N_0$, and let $(x_i)_{i \geqslant 0}$ be its orbit under $S$.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item If $x_0 = 0$, or if the odd part of $x_0$ is of the form $2^m \pm 1$ with $m \geqslant 1$ or lies in $\{11, 23, 181\}$, the orbit reaches the fixed point $0$.
        \item For every other $x_0$, the orbit satisfies $x_i \to \infty$ as $i \to \infty$.
    \end{enumerate}

\label{lem: odd step}
    Let $y \geqslant 3$ be odd, and write $y$ as in the decomposition \eqref{eq: decomposition}.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item $Q_-(y) = 2^{j-1} k y$ and $Q_-^j(y) = k (2^j k + 1)$.
        \item $Q_+(y) = 2^{j-1} k y$ and $Q_+^j(y) = k (2^j k - 1)$.
        \item $S(y) = 2^j k (2^j k + \varepsilon)$ and $S^{j+1}(y) = k (2^j k + \varepsilon)$.
    \end{enumerate}
    That is, in each case the next odd term after $y$ in the orbit is $y' = k (2^j k + \varepsilon)$, and the terms between $y$ and $y'$ are multiples of $y'$. If $k \geqslant 3$, then $y' > y$.

By \eqref{eq: maps} and the decomposition \eqref{eq: decomposition}, $Q_-(y) = y \cdot (y - 1)/2$ with $y - 1 = 2^j k$, and $Q_+(y) = y \cdot (y + 1)/2$ with $y + 1 = 2^j k$. In both cases, this is $2^{j-1} k y$. The $j - 1$ halvings that follow take $2^{j-1} k y$ to the odd number $y' = k y = k (2^j k + \varepsilon)$ through multiples of $y'$. If $k \geqslant 3$, then $y' = k y > y$.

    Under $S$, we have $y + \varepsilon = 2^{j+1} k + 2 \varepsilon = 2 (2^j k + \varepsilon)$, so
    \begin{equation*}
        y^2 - 1 = (y - \varepsilon)(y + \varepsilon) = 2^{j+2} k \bigl( 2^j k + \varepsilon \bigr) ,
    \end{equation*}
    which gives $S(y)$. The number $2^j k + \varepsilon$ is odd, since $j \geqslant 1$, so $j$ halvings take $S(y)$ to the odd number $y' = k (2^j k + \varepsilon)$ through multiples of $y'$. If $k \geqslant 3$, then
    \begin{equation*}
        y' - y = 2^j k (k - 2) + \varepsilon (k - 1) \geqslant 2k (k - 2) - (k - 1) > 0 .
    \end{equation*}

\label{lem: orbit}
    Let $x_0 \geqslant 1$ have odd part $q > 1$, and let $(x_i)_{i \geqslant 0}$ be its orbit under $Q_-$, $Q_+$ or $S$.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item Under $Q_-$ and $Q_+$, $q$ divides $x_i$ for every $i \geqslant 0$.
        \item Let $y_0 = q$, $y_1$, $y_2$, $\dots$ be the odd terms of the orbit, in order of occurrence. For $y_r \geqslant 3$, let $j_r$, $k_r$ and $\varepsilon_r$ be the numbers of the decomposition \eqref{eq: decomposition} for $y = y_r$. By Lemma~\ref{lem: odd step},
        \begin{equation}
            y_{r+1} = k_r \bigl( 2^{j_r} k_r + \varepsilon_r \bigr) .
            \label{eq: odd terms}
        \end{equation}
        If some $y_r$ is a terminal number, then under $Q_-$ and $Q_+$ the orbit enters the cycle \eqref{eq: cycle} that contains $y_r$, and under $S$ it reaches the fixed point $0$. Otherwise $k_r \geqslant 3$ for every $r$, and $x_i \to \infty$ as $i \to \infty$.
    \end{enumerate}

\label{lem: reduction}
    Let $x_0 \geqslant 1$ have odd part $q > 1$, and consider its orbit under $Q_-$, $Q_+$ or $S$. Assume that $q$ is not a terminal number of the map, and that some odd term of the orbit is a terminal number. Let $r$ be the least index such that $y_r$ is a terminal number, where $y_r$ is as in Lemma~\ref{lem: orbit}~(ii). Then $r \geqslant 1$, $k_{r-1} \geqslant 3$, and $j = j_{r-1}$, $k = k_{r-1}$ give the following solutions of \eqref{eq: key}.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item Under $Q_-$, $y_r = 2^m + 1$ with $m \geqslant 1$, and $k_{r-1} (2^{j_{r-1}} k_{r-1} + 1) = 2^m + 1$.
        \item Under $Q_+$, $y_r = 2^m - 1$ with $m \geqslant 1$, and $k_{r-1} (2^{j_{r-1}} k_{r-1} - 1) = 2^m - 1$.
        \item Under $S$, $y_r = 2^m + \delta$ with $m \geqslant 1$ and $\delta \in \{-1, 1\}$, and $k_{r-1} (2^{j_{r-1}} k_{r-1} + \varepsilon_{r-1}) = 2^m + \delta$.
    \end{enumerate}

Since $y_0 = q$ is not a terminal number, we have $r \geqslant 1$. By the minimality of $r$, the terms $y_0, \dots, y_{r-1}$ are not terminal numbers. As in the proof of Lemma~\ref{lem: orbit}, induction gives $y_{r-1} \geqslant 3$ and $k_{r-1} \geqslant 3$. By \eqref{eq: odd terms},
    \begin{equation*}
        y_r = k_{r-1} \bigl( 2^{j_{r-1}} k_{r-1} + \varepsilon_{r-1} \bigr) ,
    \end{equation*}
    where $\varepsilon_{r-1} = 1$ under $Q_-$ and $\varepsilon_{r-1} = -1$ under $Q_+$ by the decomposition \eqref{eq: decomposition}. The terminal number $y_r$ is $2^m + 1$ under $Q_-$, $2^m - 1$ under $Q_+$, and $2^m \pm 1$ under $S$, with $m \geqslant 1$. This proves (i), (ii) and (iii).

\label{lem: szalay}
    Consider the solutions of $2^a \pm 2^b + 1 = z^2$ in positive integers $a$, $b$ and $z$.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item The solutions of $2^a + 2^b + 1 = z^2$ with $a \geqslant b$ are
        \begin{equation*}
            (a, b, z) = (2u, u + 1, 2^u + 1) \ \text{ with } u \geqslant 1 , \qquad (5, 4, 7) , \qquad (9, 4, 23) .
        \end{equation*}
        \item The solutions of $2^a - 2^b + 1 = z^2$ with $a > b$ are
        \begin{equation*}
            (a, b, z) = (2u, u + 1, 2^u - 1) \ \text{ with } u \geqslant 2 , \qquad (5, 3, 5) , \qquad (7, 3, 11) , \qquad (15, 3, 181) .
        \end{equation*}
    \end{enumerate}

\label{lem: key}
    The solutions of \eqref{eq: key} are given by the identities \eqref{eq: solutions}, that is, $(j, k, \varepsilon, m, \delta)$ is $(1, 3, -1, 4, -1)$, $(2, 3, -1, 5, 1)$ or $(1, 45, 1, 12, -1)$. In particular, the following hold for \eqref{eq: key} with $\varepsilon = \delta$.
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item The equation $k (2^j k + 1) = 2^m + 1$ has no solution.
        \item The only solution of $k (2^j k - 1) = 2^m - 1$ is $(j, k, m) = (1, 3, 4)$.
    \end{enumerate}

\label{rem: descent}
    The proof of \citep[Lemma~2]{sedaghat2020dual} writes $k - 1 = 2^{\alpha_1} h_1$, then $h_1 + 1 = 2^{\alpha_2} h_2$. In general, it writes $h_i + 1$ or $h_i - 1$ as $2^{\alpha_{i+1}} h_{i+1}$ with $h_{i+1}$ odd. \citet{sedaghat2020dual} denotes $\alpha_i$ and $h_i$ by $j_i$ and $k_i$. At each reduction, the proof divides the equation by the least power of $2$ among its terms. The reduction is impossible when $h_i - 1 = 0$, and the proof does not treat this case.

    For fixed $j, m \geqslant 1$, reducing $k (2^j k + 1) = 2^m + 1$ modulo any given power of $2$ does not exclude a solution. For fixed $j \geqslant 1$ and integers $k$, $k'$,
    \begin{equation*}
        \bigl( 2^j k^2 + k \bigr) - \bigl( 2^j k'^2 + k' \bigr) = (k - k') \bigl( 2^j (k + k') + 1 \bigr) ,
    \end{equation*}
    and the factor $2^j (k + k') + 1$ is odd. Hence the map $k \mapsto 2^j k^2 + k$ is injective, and therefore bijective, modulo every power of $2$. In particular, the congruence $2^j k^2 + k \equiv 2^m + 1$ has a solution modulo every power of $2$, and this solution is odd, since $2^j k^2 + k \equiv k \pmod 2$.

    We apply the same descent to $k (2^j k - 1) = 2^m - 1$, which is \eqref{eq: key} with $\varepsilon = \delta = -1$. Write it as $2^j k^2 - k + 1 = 2^m$. Since $k \geqslant 3$, this gives $2^m > 2^j$. Write $k - 1 = 2^{\alpha_1} h_1$ with $h_1$ odd, so that
    \begin{equation*}
        2^j k^2 - 2^{\alpha_1} h_1 = 2^m .
    \end{equation*}
    As $k$ and $h_1$ are odd and $m > j$, comparing the exponents of $2$ in the terms of this equation forces $\alpha_1 = j$. Division by $2^j$ gives $k^2 - h_1 = 2^{m-j}$. Substituting $k = 2^j h_1 + 1$ gives
    \begin{equation*}
        2^{2j} h_1^2 + 2^{j+1} h_1 + 1 - h_1 = 2^{m-j} ,
    \end{equation*}
    and the next reduction would write $h_1 - 1$ as $2^{\alpha_2} h_2$. At the solution $(j, k, m) = (1, 3, 4)$ of Lemma~\ref{lem: key}~(ii), $h_1 = 1$, and the descent stops. If the descent continued indefinitely, it would exclude this solution, and hence the bounded orbits of $5$ under $Q_+$ and of $11$ under $S$.

\label{cor: bounded}
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item For $X \geqslant 2$, at most $(\log_2 X + 1)^2$ initial values in $\{0, 1, \dots, X\}$ have a bounded orbit under $Q_-$, and the same bound holds under $Q_+$.
        \item For $X \geqslant 2$, at most $(\log_2 X + 3)^2$ initial values in $\{0, 1, \dots, X\}$ have a bounded orbit under $S$.
        \item An orbit under $Q_-$ that contains an odd term $2^m - 1$ with $m \geqslant 3$ tends to infinity.
        \item An orbit under $Q_+$ that contains an odd term $2^m + 1$ with $m \geqslant 3$ tends to infinity.
    \end{enumerate}

Under $Q_-$, by Theorem~\ref{thm: minus}, a bounded orbit starts from $0$, from a power $2^l \leqslant X$, or from $2^l (2^m + 1) \leqslant X$. There are at most $\log_2 X + 1$ powers $2^l \leqslant X$. For the initial values $2^l (2^m + 1) \leqslant X$,
    \begin{equation*}
        2^{l+m} < 2^l (2^m + 1) \leqslant X , \qquad \text{so} \qquad l + m < \log_2 X ,
    \end{equation*}
    and at most $\log_2 X \, (\log_2 X + 1)/2$ pairs $(l, m)$ with $l \geqslant 0$ and $m \geqslant 1$ qualify. Since $\log_2 X \geqslant 1$, the total is at most
    \begin{equation*}
        1 + (\log_2 X + 1) + \frac{\log_2 X \, (\log_2 X + 1)}{2} \leqslant (\log_2 X + 1)^2 .
    \end{equation*}

    Under $Q_+$, by Theorem~\ref{thm: plus}, a bounded orbit starts from $0$, from $2^l (2^m - 1) \leqslant X$, or from $5 \cdot 2^l \leqslant X$. For the initial values $2^l (2^m - 1) \leqslant X$,
    \begin{equation*}
        2^{l+m-1} \leqslant 2^l (2^m - 1) \leqslant X , \qquad \text{so} \qquad l + m \leqslant \log_2 X + 1 ,
    \end{equation*}
    and at most $(\log_2 X + 1)(\log_2 X + 2)/2$ pairs $(l, m)$ qualify. For $5 \cdot 2^l \leqslant X$, we have $2^{l+2} < X$, which leaves at most $\log_2 X - 1$ values of $l$. Since $\log_2 X \geqslant 1$, the total is at most
    \begin{equation*}
        1 + \frac{(\log_2 X + 1)(\log_2 X + 2)}{2} + \log_2 X - 1 \leqslant (\log_2 X + 1)^2 .
    \end{equation*}
    This proves (i).

    Under $S$, by Theorem~\ref{thm: S}, a bounded orbit starts from $0$, from $2^l (2^m - 1) \leqslant X$, from $2^l (2^m + 1) \leqslant X$, or from $2^l c \leqslant X$ with $c \in \{11, 23, 181\}$. The counts above bound the families $2^l (2^m - 1)$ and $2^l (2^m + 1)$ by $(\log_2 X + 1)(\log_2 X + 2)/2$ and $\log_2 X \, (\log_2 X + 1)/2$, respectively. For each $c$, we have $2^{l+3} < 2^l c \leqslant X$, which leaves at most $\log_2 X$ values of $l$. The total is at most
    \begin{equation*}
        1 + \frac{(\log_2 X + 1)(\log_2 X + 2)}{2} + \frac{\log_2 X \, (\log_2 X + 1)}{2} + 3 \log_2 X \leqslant (\log_2 X + 3)^2 .
    \end{equation*}
    This proves (ii).

    Under $Q_-$, from the odd term $2^m - 1$ on, the orbit is the orbit of the initial value $2^m - 1$. For $m \geqslant 3$, this number is at least $7$ and congruent to $3$ modulo $4$, whereas every terminal number of $Q_-$ that is at least $7$ is congruent to $1$ modulo $4$. So $2^m - 1$ is neither a terminal number nor a power of $2$, and Theorem~\ref{thm: minus}~(iii) applies. This proves (iii).

    Under $Q_+$, from the odd term $2^m + 1$ on, the orbit is the orbit of the initial value $2^m + 1$. For $m \geqslant 3$, this number is at least $9$ and congruent to $1$ modulo $4$, whereas every terminal number of $Q_+$ that is at least $9$ is congruent to $3$ modulo $4$. So $2^m + 1$ is neither a terminal number nor $5$, and Theorem~\ref{thm: plus}~(iv) applies. This proves (iv).

\label{thm: criterion}
    \begin{enumerate}[(i)]
        \setlength{\itemsep}{0pt}
        \item Let $x_0 \geqslant 1$, and let $y > 1$ be an odd term of its orbit $(x_i)_{i \geqslant 0}$ under $Q_-$. If $y$ divides none of the numbers $2^m + 1$ with $m \geqslant 1$, then $x_i \to \infty$ as $i \to \infty$.
        \item An odd integer $y > 1$ divides $2^m + 1$ for some $m \geqslant 1$ if and only if there is $s \geqslant 1$ with $v_2(\operatorname{ord}_p(2)) = s$ for every prime $p$ dividing $y$.
    \end{enumerate}

Let $i_0$ be an index with $x_{i_0} = y$. Lemma~\ref{lem: orbit}~(i), applied to the orbit of $y$, shows that $y$ divides $x_i$ for every $i \geqslant i_0$. If $x_i$ does not tend to infinity, Lemma~\ref{lem: orbit}~(ii), applied to the orbit of $y$, gives an index $i_1 \geqslant i_0$ and an integer $m \geqslant 1$ with $x_{i_1} = 2^m + 1$. Then $y$ divides $2^m + 1$, which contradicts the assumption on $y$. This proves (i).

    For (ii), let $p$ be a prime dividing $y$, and let $p^e$ be the largest power of $p$ dividing $y$. We show that, for every $m \geqslant 1$,
    \begin{equation*}
        2^m \equiv -1 \pmod{p^e} \quad \Longleftrightarrow \quad \operatorname{ord}_{p^e}(2) \text{ divides } 2m \text{ and not } m .
    \end{equation*}
    If $2^m \equiv -1 \pmod{p^e}$, then $2^{2m} \equiv 1$ and $2^m \not\equiv 1$ modulo $p^e$. This gives the forward implication. Conversely, assume that $\operatorname{ord}_{p^e}(2)$ divides $2m$ and not $m$. Then $p^e$ divides the product $(2^m - 1)(2^m + 1)$ but not $2^m - 1$. These factors differ by $2$, so $p$ does not divide both, and $p^e$ divides $2^m + 1$. Equivalently, the condition on $\operatorname{ord}_{p^e}(2)$ reads
    \begin{equation}
        v_2(m) = v_2 \bigl( \operatorname{ord}_{p^e}(2) \bigr) - 1 \quad \text{and} \quad \text{the odd part of } \operatorname{ord}_{p^e}(2) \text{ divides } m .
        \label{eq: local condition}
    \end{equation}
    Moreover, $v_2(\operatorname{ord}_{p^e}(2)) = v_2(\operatorname{ord}_p(2))$. Indeed, $\operatorname{ord}_p(2)$ divides $\operatorname{ord}_{p^e}(2)$, since $2^{\operatorname{ord}_{p^e}(2)} \equiv 1 \pmod p$. By the binomial theorem, if an integer is congruent to $1$ modulo $p^f$ with $f \geqslant 1$, its $p$-th power is congruent to $1$ modulo $p^{f+1}$. Applying this $e - 1$ times, starting from $2^{\operatorname{ord}_p(2)} \equiv 1 \pmod p$, gives
    \begin{equation*}
        2^{\operatorname{ord}_p(2) \, p^{e-1}} \equiv 1 \pmod{p^e} ,
    \end{equation*}
    so $\operatorname{ord}_{p^e}(2)$ divides $\operatorname{ord}_p(2) \, p^{e-1}$. The quotient $\operatorname{ord}_{p^e}(2) / \operatorname{ord}_p(2)$ therefore divides the odd number $p^{e-1}$, and the $2$-adic valuations agree.

    Now $y$ divides $2^m + 1$ if and only if \eqref{eq: local condition} holds for every prime $p$ dividing $y$. If such an $m$ exists, then $v_2(\operatorname{ord}_p(2)) = v_2(m) + 1$ for every prime $p$ dividing $y$. Conversely, assume that $v_2(\operatorname{ord}_p(2)) = s \geqslant 1$ for every such $p$. Let $m$ be $2^{s-1}$ times the least common multiple of the odd parts of the orders $\operatorname{ord}_{p^e}(2)$. Then $m$ satisfies \eqref{eq: local condition} for every $p$. This proves (ii).
